 Json? // array of {name, url, type}\n  createdAt            DateTime            @default(now())\n  updatedAt            DateTime            @updatedAt\n  channel              Channel?            @relation(fields: [channelId], references: [id], onDelete: Cascade)\n  directConversation   DirectConversation? @relation(fields: [directConversationId], references: [id], onDelete: Cascade)\n  user                 User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replyTo              Message?            @relation(\"MessageReply\", fields: [replyToId], references: [id], onDelete: SetNull)\n  replies              Message[]           @relation(\"MessageReply\")\n  reactions            MessageReaction[]\n\n  @@index([channelId, createdAt])\n  @@index([directConversationId, createdAt])\n  @@index([replyToId])\n}\n\nmodel MessageReaction {\n  id        String   @id @default(cuid())\n  messageId String\n  userId    String\n  emoji     String\n  createdAt DateTime @default(now())\n  message   Message  @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([messageId, userId, emoji])\n  @@index([messageId])\n}\n\nmodel DirectConversation {\n  id        String    @id @default(cuid())\n  tenantId  String\n  user1Id   String\n  user2Id   String\n  createdAt DateTime  @default(now())\n  user1     User      @relation(\"directUser1\", fields: [user1Id], references: [id], onDelete: Cascade)\n  user2     User      @relation(\"directUser2\", fields: [user2Id], references: [id], onDelete: Cascade)\n  messages  Message[]\n\n  @@unique([user1Id, user2Id])\n}\n\n// ─── Notifications ───────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  tenantId  String\n  type      String // new_post | event_reminder | chat_mention | direct_message | course_update | member_joined